'use client';
import { useEffect, useState } from 'react';
import { useRouter } from 'next/router';
import axios from 'axios';
import Layout from '../layout';

export default function Dashboard() {
  const [clients, setClients] = useState([]);
  const [loading, setLoading] = useState(true);
  const router = useRouter();

  useEffect(() => {
    if (typeof window !== 'undefined') {
      const token = localStorage.getItem('token');
      if (!token) {
        router.push('/login');
      } else {
        const fetchClients = async () => {
          const { data } = await axios.get('http://localhost:5000/api/clients', {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          });
          setClients(data);
          setLoading(false);
        };

        fetchClients();
      }
    }
  }, [router]);

  if (loading) {
    return <div>Cargando...</div>;
  }

  return (
    <Layout>
      <div className="container mx-auto p-4">
        <h1 className="text-2xl font-bold mb-4">Clientes</h1>
        <table className="min-w-full bg-white shadow-md rounded-lg overflow-hidden">
          <thead className="bg-gray-200">
            <tr>
              <th className="py-2 px-4">Nombre Completo</th>
              <th className="py-2 px-4">Identificación</th>
              <th className="py-2 px-4">Edad</th>
              <th className="py-2 px-4">Género</th>
              <th className="py-2 px-4">Estado</th>
              <th className="py-2 px-4">Acciones</th>
            </tr>
          </thead>
          <tbody>
            {clients.map((client) => (
              <tr key={client.id} className="border-b">
                <td className="py-2 px-4">{client.fullName}</td>
                <td className="py-2 px-4">{client.identification}</td>
                <td className="py-2 px-4">{client.age}</td>
                <td className="py-2 px-4">{client.gender}</td>
                <td className="py-2 px-4">{client.isActive ? 'Activo' : 'Inactivo'}</td>
                <td className="py-2 px-4">
                  <button className="bg-blue-500 text-white px-4 py-2 rounded-md">Editar</button>
                  <button className="bg-red-500 text-white px-4 py-2 rounded-md ml-2">Eliminar</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </Layout>
  );
}